def unificar_empresa_rsc(apps, schema_editor):
    """Junta a opção vazia 'RSC' e itens duplicados no cliente RSC canônico."""
    ItemLista = apps.get_model("crm", "ItemLista")
    Atividade = apps.get_model("atividades", "AtividadeDiaria")
    rscs = [
        item
        for item in ItemLista.objects.filter(tipo="clientes_rsc").order_by("id")
        if (item.nome or "").strip().lower() == "rsc"
    ]
    if rscs:
        canon = rscs[0]
    else:
        canon = ItemLista.objects.create(
            tipo="clientes_rsc",
            nome="RSC",
            ativo=True,
            ordem=0,
        )
    for dup in rscs[1:]:
        Atividade.objects.filter(cliente_rsc_id=dup.id).update(cliente_rsc_id=canon.id)
        dup.ativo = False
        dup.nome = f"RSC duplicado {dup.id}"[:150]
        dup.save(update_fields=["ativo", "nome"])
    Atividade.objects.filter(cliente_rsc__isnull=True).update(cliente_rsc_id=canon.id)
    # Postgres: o UPDATE acima deixa gatilhos de FK pendentes, e o Django cria
    # os índices adiados logo depois; sem isto: "pending trigger events".
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


